wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The only authority this node holds is `response-channel`, which is
        // write-only: `send` is the single operation it can perform.
        let confirmation = aap::caps::response_channel::send(&reply.text);

        // The `ensures` clauses are checked on the output. If the channel did
        // not confirm delivery, or did not report a session identity, the node
        // traps rather than returning a confirmation that violates its contract.
        assert!(
            confirmation.delivered,
            "ensures violated: delivered must be true"
        );
        assert!(
            !confirmation.session.is_empty(),
            "ensures violated: session_id must be present"
        );

        DeliveryConfirmation {
            session: confirmation.session,
            delivered: confirmation.delivered,
        }
    }
}

export!(Node);
